    SELECT 1 FROM feed.ShowFeedEntry f
    JOIN mkt.ShopEvent e ON e.ShopEventId = f.ShopEventId
    WHERE e.Slug = N'collect-a-con-dallas-2026-10' AND f.SlotCode = 'CALENDAR_FEATURED' AND f.IsActive = 1)
